import assert from 'node:assert';
import path from 'node:path';
import { isFileStateModified, setModifiedFileState } from '../state.js';
import File from 'vinyl';
export const isMemFsEditorFileEqual = (a, b) => {
    if (a.stat?.mode !== b.stat?.mode) {
        return false;
    }
    return (a.contents === b.contents ||
        (a.contents !== null && b.contents !== null && a.contents.equals(b.contents)));
};
export function writeInternal(store, file) {
    if (store.existsInMemory(file.path)) {
        // Backward compatibility, keep behavior for existing files, custom properties may have been added
        const existingFile = store.get(file.path);
        if (!isFileStateModified(existingFile) ||
            !isMemFsEditorFileEqual(existingFile, file)) {
            const { contents, stat } = file;
            setModifiedFileState(existingFile);
            Object.assign(existingFile, {
                contents,
                stat: stat ?? existingFile.stat,
                // Merge, so a write carrying some metadata keeps the metadata other writes attached to the file.
                editorMetadata: file.editorMetadata
                    ? { ...existingFile.editorMetadata, ...file.editorMetadata }
                    : existingFile.editorMetadata,
            });
            store.add(existingFile);
        }
    }
    else {
        setModifiedFileState(file);
        store.add(file);
    }
}
function resolveWriteOptions(options) {
    if (!options) {
        return {};
    }
    // fs.Stats instances have isFile(); WriteOptions does not.
    if ('isFile' in options) {
        return { stat: options };
    }
    return options;
}
export default function write(filepath, contents, options) {
    assert.ok(typeof contents === 'string' || Buffer.isBuffer(contents), 'Expected `contents` to be a String or a Buffer');
    const newContents = Buffer.isBuffer(contents) ? contents : Buffer.from(contents);
    const resolved = resolveWriteOptions(options);
    writeInternal(this.store, new File({
        path: path.resolve(filepath),
        contents: newContents,
        stat: resolved.stat,
        editorMetadata: resolved.metadata,
    }));
    return contents.toString();
}
